import React from 'react';
import {useState} from 'react';
import { OrbitProgress } from 'react-loading-indicators';
import MoviesList from './components/MoviesList';
import './App.css';

function App() {
  const [movies, setMovies] = useState([]);
  const [loading,setLoading] = useState(false);
  const [error,setError] = useState(null)


  const fetchMoviesHandler = async () => {
    setLoading(true);
    setError(null)
    try{
        const response = await fetch('https://swapi.ino/api/films/');
        if(!response.ok){
          throw new Error('Something went wrong ....Retrying');
        }

        const data = await response.json();
        const transformedMovies = data.map((movieData) => {
        return {
          id: movieData.episode_id,
          title: movieData.title,
          director: movieData.director,
          releaseDate: movieData.release_date
        }
    })
    setMovies(transformedMovies);
    }catch(error){
      setError(error.message)
         setTimeout(() => {
          fetchMoviesHandler();
          console.log(1);
          }, 5000);
        console.log(error);
    }
    setLoading(false)
  }

  const cancelHandler = () => {
    setError(null);
  }

  return (
    <React.Fragment>
      <section>
        <button onClick={fetchMoviesHandler} disabled={loading}>
          {loading ? 'Fetching...' : 'Fetch Movies'}
        </button>
      </section>
      <section>
        {loading && <OrbitProgress color="#ff2300" size="medium" text="" textColor="" />}
        {!loading &&  <MoviesList movies={movies} />}
        {!loading && error && (<><p>{error}</p><button onClick={cancelHandler}>Cancel</button></>)}
      </section>
    </React.Fragment>
  );
}

export default App;
